    /**
     * Tests getting all LoanAccounts.
     *
     * @return    Collection
     */
    public List<LoanAccount> testGetAll() throws Throwable {
    LOGGER.info( "LoanAccountTest:testGetAll() - Retrieving Collection of LoanAccounts:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all LoanAccount : " );
    List<LoanAccount> collection  = null;

    try {
        // call the static get method on the LoanAccountService
        collection = service.getAllLoanAccount();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            LoanAccount currEntity  = null;
            Iterator<LoanAccount> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getLoanAccountId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

